// Prepara la página 1 del formulario: servicios activos (desde Supabase) y, si venimos de un
// reintento por datos no válidos, los datos ya escritos para no perderlos.
const services = $('Cargar servicios').first().json.services ?? [];

let retry = {};
try { if ($('Reintento datos').isExecuted) retry = $('Reintento datos').last().json; } catch (e) { /* primera vez */ }
const p = retry.prefill ?? {};

const fields = [
  { fieldLabel: 'Servicio', fieldType: 'dropdown', requiredField: true,
    defaultValue: p.servicio ?? '',
    fieldOptions: { values: services.map((s) => ({ option: s.name })) } },
  { fieldLabel: 'Día deseado', fieldType: 'date', requiredField: true, defaultValue: p.dia ?? '' },
  { fieldLabel: 'Nombre y apellidos', fieldType: 'text', requiredField: true, placeholder: 'Ana Pérez', defaultValue: p.nombre ?? '' },
  { fieldLabel: 'Correo electrónico', fieldType: 'email', requiredField: true, placeholder: 'ana@ejemplo.com', defaultValue: p.email ?? '' },
  { fieldLabel: 'Teléfono', fieldType: 'text', requiredField: true, placeholder: '+34 600 123 456', defaultValue: p.telefono ?? '' },
  { fieldLabel: 'Privacidad', fieldType: 'checkbox', requiredField: true,
    fieldOptions: { values: [{ option: 'He leído y acepto la política de privacidad' }] } },
];

const description = (retry.error ? `⚠️ ${retry.error}\n\n` : '')
  + 'Usaremos tus datos solo para gestionar tu turno. En el siguiente paso verás las horas libres del día elegido.';

return [{ json: { services, fields, description, hasServices: services.length > 0 } }];

// Valida la página 1. (La base de datos vuelve a validar todo al reservar: esto es solo para
// dar un mensaje claro y dejar al usuario corregir sin perder lo escrito.)
const s = $input.first().json;
// Si la persona abandonó la página, al vencer la espera n8n continúa SIN datos del formulario: se termina aquí.
if (s['Servicio'] === undefined && s['Correo electrónico'] === undefined) return [{ json: { ok: false, abandoned: true } }];
const services = $('Preparar página 1').last().json.services ?? [];

const serviceName = String(s['Servicio'] ?? '');
const day = String(s['Día deseado'] ?? '').trim();
const name = String(s['Nombre y apellidos'] ?? '').trim();
const email = String(s['Correo electrónico'] ?? '').trim().toLowerCase();
const phone = String(s['Teléfono'] ?? '').trim();
const privacy = Array.isArray(s['Privacidad']) ? s['Privacidad'].length > 0 : Boolean(s['Privacidad']);

const prefill = { servicio: serviceName, dia: day, nombre: name, email, telefono: phone };
const digits = phone.replace(/\D/g, '').length;
const svc = services.find((x) => x.name === serviceName);

let error = null;
if (!svc) error = 'Elige un servicio de la lista.';
else if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) error = 'Elige un día válido.';
else if (!name || name.length > 120) error = 'Escribe tu nombre.';
else if (email.length > 254 || !/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(email)) error = 'El correo electrónico no parece válido.';
else if (!/^\+?[0-9][0-9 ().-]{5,24}$/.test(phone) || digits < 7 || digits > 15) error = 'El teléfono no es válido (usa números, espacios y, si quieres, el prefijo +34).';
else if (!privacy) error = 'Para reservar debes aceptar la política de privacidad.';

return [{ json: error
  ? { ok: false, error, prefill }
  : { ok: true, prefill, data: { service_id: svc.id, service_name: svc.name, day, name, email, phone } } }];

// Prepara la vuelta a la página 1 conservando lo escrito.
// Llega desde "¿Datos válidos?" (error en texto) o desde la reserva (INVALID_INPUT de la base de datos).
const j = $input.first().json;
if (j.abandoned) return [];   // formulario abandonado (venció la espera): no hay nada que reintentar
let prefill = j.prefill;
let error = j.error;

if (j.error === 'INVALID_INPUT' || !prefill) {
  prefill = $('Validar datos').last().json.prefill;
  const campo = { name: 'tu nombre', email: 'tu correo electrónico', phone: 'tu teléfono' }[j.field] ?? 'los datos';
  error = `Revisa ${campo}.`;
}
return [{ json: { error, prefill } }];

// Punto único de entrada a "ver horas libres". Lo alimentan tres caminos:
//   · datos válidos de la página 1          · cambio de día (día completo)
//   · "Ese turno acaba de ocuparse" (vuelve a elegir hora SIN perder los datos)
// Todos traen { data, notice? }.
const j = $input.first().json;
return [{ json: {
  state: { data: j.data, notice: j.notice ?? null },
  p_service_id: j.data.service_id,
  p_day: j.data.day,
} }];

// ---- utilidades compartidas (se copian dentro de los nodos Code que las usan) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Fecha larga en español a partir de 'YYYY-MM-DD' (ya es la fecha LOCAL: la calcula la base de datos).
const fechaLarga = (ymd) => new Intl.DateTimeFormat('es-ES', {
  timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
}).format(new Date(ymd + 'T12:00:00Z'));

// --- .ics (RFC 5545): horas en UTC, así el cambio de hora no afecta ---
const icsEsc = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const icsFold = (line) => {                       // líneas de máx. 75 octetos
  let out = '', cur = '', bytes = 0, first = true;
  for (const ch of line) {
    const b = Buffer.byteLength(ch);
    if (bytes + b > (first ? 75 : 74)) { out += cur + '\r\n '; cur = ''; bytes = 0; first = false; }
    cur += ch; bytes += b;
  }
  return out + cur;
};
const icsTime = (iso) => iso.replace(/[-:]/g, '').replace(/\.\d+/, '');   // 2026-11-09T09:00:00Z -> 20261109T090000Z
// sequence: versión del evento (la lleva la base de datos: 0 reserva, +1 por cada cambio o cancelación).
// Sin indicarla se usa la de la Fase 1: 0 (confirmado) / 1 (cancelado).
function buildIcs({ uid, start, end, summary, description, url, cancelled, sequence }) {
  const now = new Date().toISOString().slice(0, 19) + 'Z';
  const lines = [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Turnos//n8n//ES', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    `UID:${uid}@turnos`,
    `DTSTAMP:${icsTime(now)}`,
    `DTSTART:${icsTime(start)}`,
    `DTEND:${icsTime(end)}`,
    `SUMMARY:${icsEsc(summary)}`,
    `DESCRIPTION:${icsEsc(description)}`,
    url ? `URL:${url}` : null,
    `STATUS:${cancelled ? 'CANCELLED' : 'CONFIRMED'}`,
    `SEQUENCE:${sequence ?? (cancelled ? 1 : 0)}`,
    ...(cancelled ? [] : ['BEGIN:VALARM', 'TRIGGER:-PT1H', 'ACTION:DISPLAY', 'DESCRIPTION:Recordatorio de turno', 'END:VALARM']),
    'END:VEVENT', 'END:VCALENDAR',
  ].filter(Boolean);
  return lines.map(icsFold).join('\r\n') + '\r\n';
}

// --- enlaces de gestión: <url del formulario>?codigo=<código secreto> ---
const enlaceCon = (base, code) => {
  const b = String(base ?? '');
  return b ? b + (b.includes('?') ? '&' : '?') + 'codigo=' + code : '';
};
const dmy = (ymd) => String(ymd).split('-').reverse().join('/');          // 2026-11-09 -> 09/11/2026

// --- avisos a quien atiende (inmediatos y resumen): misma plantilla sencilla ---
// filas: [[etiqueta, valor], ...]  ->  { text, html }
