  return { text, html };
}
// Destinatario del aviso: staff_email (o, si está vacío, admin_email: lo resuelve get_config); nunca queda sin destino.
const destinoPersonal = (cfg, conf) => cfg.staff_email || cfg.admin_email || conf.from_email;

// El día elegido está lleno: se ofrecen los próximos días con huecos.
const p = $input.first().json;
const opciones = p.nextDays.map((n) => ({
  day: n.day,
  label: `${fechaLarga(n.day)} · ${n.free_slots} ${n.free_slots === 1 ? 'hora libre' : 'horas libres'}`,
}));
return [{ json: {
  data: p.data,
  opciones,
  fields: [{ fieldLabel: 'Otro día', fieldType: 'dropdown', requiredField: true,
             fieldOptions: { values: opciones.map((o) => ({ option: o.label })) } }],
  description: `No quedan horas libres el ${p.dayLabel}. Estos son los próximos días con huecos:`,
} }];

if ($input.first().json['Otro día'] === undefined) return [];   // formulario abandonado (venció la espera): fin
const prep = $('Preparar página de días').last().json;
const elegido = prep.opciones.find((o) => o.label === $input.first().json['Otro día']) ?? prep.opciones[0];
return [{ json: { data: { ...prep.data, day: elegido.day }, notice: null } }];

