<tr><td style="padding:6px 12px 6px 0;color:#6b7280">Día</td><td><b>${esc(fecha)}</b></td></tr>
<tr><td style="padding:6px 12px 6px 0;color:#6b7280">Hora</td><td><b>${esc(r.local_time)}</b> (hora de ${esc(r.timezone)})</td></tr></table>
